	'messages:right-pagelang' => 'ml:താളിന്റെ ഭാഷ മാറ്റുക',
	'messages:action-pagelang' => 'ml:താളിന്റെ ഭാഷ മാറ്റുക',
	'messages:log-name-pagelang' => 'ml:ഭാഷ മാറ്റലിന്റെ രേഖ',
